cypress_script:
describe('Shopping Cart Functionality', () => {
  before(() => {
    cy.visit('https://www.saucedemo.com/');
    cy.get('[data-test="username"]').type('standard_user');
    cy.get('[data-test="password"]').type('secret_sauce');
    cy.get('[data-test="login-button"]').click();
  });

  it('should display the shopping cart with correct elements', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.title().should('eq', 'Swag Labs');
    cy.get('[data-test="secondary-header"]').should('be.visible').and('contain.text', 'Your Cart');
    cy.get('[data-test="continue-shopping"]').should('be.visible');
    cy.get('[data-test="checkout"]').should('be.visible');
  });

  it('should remain on the same page when no items are present in the cart', () => {
    cy.visit('https://www.saucedemo.com/cart.html');
    cy.url().should('include', '/cart.html');
    cy.get('[data-test="cart-contents-container"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Shopping Cart Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.fill('[data-test="username"]', 'standard_user');
    await page.fill('[data-test="password"]', 'secret_sauce');
    await page.click('[data-test="login-button"]');
  });

  test('should display the shopping cart with correct elements', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await expect(page).toHaveTitle('Swag Labs');
    await expect(page.locator('[data-test="secondary-header"]').first()).toBeVisible();
    await expect(page.locator('[data-test="secondary-header"]').first()).toHaveText('Your Cart');
    await expect(page.locator('[data-test="continue-shopping"]').first()).toBeVisible();
    await expect(page.locator('[data-test="checkout"]').first()).toBeVisible();
  });

  test('should remain on the same page when no items are present in the cart', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/cart.html');
    await expect(page).toHaveURL(/cart.html/);
    await expect(page.locator('[data-test="cart-contents-container"]').first()).toBeVisible();
  });
});
